create or replace function public.ensure_team_game_membership() returns trigger language plpgsql security definer set search_path='' as $$ declare v_game text; begin if tg_table_name='teams' then insert into public.team_game_rosters(team_id,game) values(new.id,new.game) on conflict do nothing; return new; end if; if tg_op='DELETE' then delete from public.team_game_members where team_id=old.team_id and user_id=old.user_id; return old; end if; if new.status='active' then select game into v_game from public.teams where id=new.team_id; insert into public.team_game_rosters(team_id,game) values(new.team_id,v_game) on conflict do nothing; insert into public.team_game_members(team_id,game,user_id) values(new.team_id,v_game,new.user_id) on conflict do nothing; else delete from public.team_game_members where team_id=new.team_id and user_id=new.user_id; end if; return new; end $$;
create trigger team_default_game_roster after insert on public.teams for each row execute function public.ensure_team_game_membership();
create trigger team_membership_game_roster after insert or update of status on public.team_members for each row execute function public.ensure_team_game_membership();
revoke all on function public.ensure_team_game_membership() from public,anon,authenticated;
create or replace function public.set_team_games(p_team_id uuid,p_games text[]) returns void language plpgsql security definer set search_path='' as $$ declare v_primary text; begin if auth.uid() is null or not private.is_team_captain(p_team_id) then raise exception 'Team captain required'; end if; select game into v_primary from public.teams where id=p_team_id for update; if v_primary is null then raise exception 'Team not found'; end if; if coalesce(cardinality(p_games),0)<1 or cardinality(p_games)>5 or not(p_games <@ array['cs2','val','lol','rl','eafc']::text[]) or not(v_primary=any(p_games)) then raise exception 'Include the team primary game and select supported games'; end if; if exists(select 1 from public.tournament_registrations where team_id=p_team_id and status in ('pending','approved','checked_in')) and exists(select 1 from public.team_game_rosters where team_id=p_team_id and not(game=any(p_games))) then raise exception 'Rosters are locked while registered'; end if; insert into public.team_game_rosters(team_id,game) select p_team_id,x from unnest(p_games) x on conflict do nothing; delete from public.team_game_rosters where team_id=p_team_id and not(game=any(p_games)); end $$;
